{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01WexYNpg6WajK8Myk4uDqxB","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"\\\\\\\"\\\\\\\"\\\\\\\"Visualize KL vs Magnitude mask divergence for paper figures.\\\\n\\\\nGenerates 3 publication-quality figures:\\\\n1. Per-layer mask comparison heatmap (KL, Magnitude, Divergence)\\\\n2. Token-level mask dynamics for single layer\\\\n3. Per-layer Jaccard divergence bar chart\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\nimport argparse\\\\nimport gc\\\\nimport importlib.util\\\\nimport json\\\\nimport os\\\\nimport sys\\\\n\\\\nimport torch\\\\nimport numpy as np\\\\nimport matplotlib\\\\nmatplotlib.use(\\\\\\\"Agg\\\\\\\")\\\\nimport matplotlib.pyplot as plt\\\\nfrom matplotlib.gridspec import GridSpec\\\\n\\\\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\\\\nfrom predictor import PredictorWrapper\\\\nfrom data_utils import get_eval_dataset\\\\nfrom transformers import AutoModelForCausalLM, AutoTokenizer\\\\n\\\\nplt.rcParams.update({\\\\n    \\\\\\\"font.size\\\\\\\": 7,\\\\n    \\\\\\\"axes.labelsize\\\\\\\": 7,\\\\n    \\\\\\\"xtick.labelsize\\\\\\\": 6,\\\\n    \\\\\\\"ytick.labelsize\\\\\\\": 6,\\\\n    \\\\\\\"font.family\\\\\\\": \\\\\\\"sans-serif\\\\\\\",\\\\n})\\\\n\\\\n\\\\ndef _best_attn():\\\\n    if importlib.util.find_spec(\\\\\\\"flash_attn\\\\\\\"):\\\\n        return \\\\\\\"flash_attention_2\\\\\\\"\\\\n    return \\\\\\\"sdpa\\\\\\\"\\\\n\\\\n\\\\ndef compute_static_mag_masks(model, sparsity):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Gate_proj weight L2 norm per neuron -> top-k mask (static).\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    masks, norms = {}, {}\\\\n    D = model.config.intermediate_size\\\\n    k = int(D * (1 - sparsity))\\\\n    for li, layer in enumerate(model.model.layers):\\\\n        w = layer.mlp.gate_proj.weight.float()\\\\n        n = w.norm(dim=1).cpu()\\\\n        _, idx = n.topk(k)\\\\n        m = torch.zeros(D, d